insert into public.tips (id, unit_id, title_en, body_md, status) values
  ('ca70ea7e-54b8-5bf6-b69b-20ddc2a37bcd', '06d1371f-27e8-5be1-a3df-a530cc9eefe3', 'Comprara, sacara, cerrara', 'Any *-ar* verb works the same way: take the *ellos* past (*compraron*), swap **-ron** for **-ra**. «Comprá pan» → **me pidió que comprara pan**; «Cerrá la puerta» → **me dijo que cerrara la puerta**; «Apagá la luz» → **que apagara la luz**.', 'draft'),
  ('2bf931e1-9673-5e55-aa7e-198aafe4ff0d', '06d1371f-27e8-5be1-a3df-a530cc9eefe3', 'Llegáramos, trajeran', 'The other persons follow: **nos pidió que llegáramos temprano** — *she asked us to get there early*; **les dijo que trajeran algo** — *he told them to bring something*. **Me encargó que le llevara** is the errand version: *she asked me to take her…*', 'draft'),
  ('69332cd2-1d6f-5d55-9be4-d460fab44716', '06d1371f-27e8-5be1-a3df-a530cc9eefe3', 'De parte de…', 'Passing on a message ends with who it''s from: **saludos de parte de mi vieja**. And the classic order from home, told later: «Portate bien» → **me dijo que me portara bien**.', 'draft'),
  ('9435d1b3-0301-576e-85fc-0c503c472aab', 'c03bcd83-1ed7-5fb6-a4e9-dae2cd690f4b', 'Fijate si…', 'Before you cross the city, you check: **fijate si abren el feriado**, **me fijo si hay turno**, **preguntale si tienen stock**. The **si** is *whether*; the verb after it stays normal.', 'draft'),
  ('c756f18a-a769-586d-a465-3143dbe5c849', 'c03bcd83-1ed7-5fb6-a4e9-dae2cd690f4b', 'Me preguntaron si…', 'Told later, the question moves into the past with its **si**: «¿Tenés turno?» → **me preguntaron si tenía turno**.', 'draft'),
  ('787e171d-c6b2-56b6-bfd5-86c95f58c4b7', 'e46f81c7-cdca-5d51-8738-55a0efa5a020', 'Mire, espere, tome', 'Usted commands flip the vowel: *mirar* → **mire**, *esperar* → **espere**, *tomar* → **tome**. The *-er* and *-ir* verbs go the other way: *venir* → **venga**, *decir* → **dígame**. **Tome, acá tiene** is how the kiosquero hands you the change.', 'draft'),
  ('0da84ce9-08d5-56d5-bf04-81b8a54b1746', 'e46f81c7-cdca-5d51-8738-55a0efa5a020', 'Don, doña', 'The old neighbour is **don José** or **doña Rosa** — first name, with respect. A **persona mayor**, a **jubilado**, gets **usted**, **cómo no** (*of course*) and **con permiso** as you squeeze past. **Perdone** if you bump into them.', 'draft'),
  ('d08e315b-8334-5c62-8039-37fca7782609', '8615c579-1ee7-516d-8329-85243ee4db53', 'Comprara, llegáramos, trajeran', 'The errand told later: **me pidió que comprara pan**, **nos dijo que llegáramos temprano**, **les pidió que trajeran algo**. The question: **preguntale si tienen stock**.', 'draft'),
  ('e05a6f2c-db31-58b3-91ea-a33abfd335c9', '8615c579-1ee7-516d-8329-85243ee4db53', 'Mire, espere, dígame', 'With **don José** and **doña Rosa**: **mire**, **espere**, **dígame**, **cómo no**.', 'draft'),
  ('0621b05f-4812-5df1-be12-84eb5d8660c1', '38987042-d239-57ac-9bcf-58be792a8609', 'Te reenvío, te paso', 'The reply has its own verbs: **te reenvío el mail** — *I''m forwarding you the email*; **te paso el link**; **te pongo en copia** — *I''m cc''ing you*. **Revisé la planilla** — *I went through the spreadsheet*.', 'draft'),
  ('4c901404-ced9-54c4-a1c0-b042f20adc93', '38987042-d239-57ac-9bcf-58be792a8609', 'Cualquier duda…', '**Cualquier duda, avisame** — *any questions, let me know* — closes half the emails in Buenos Aires. What''s still to do is **pendiente**: **me quedó pendiente el archivo**. And if it needs a meeting, you **agendás** it.', 'draft'),
  ('c1cd73a8-a9a9-5e11-a3b5-76f0696539c4', '1e64d895-153a-5af6-b41e-45c6b9da78d4', 'De golpe, para colmo', 'The twist arrives **de golpe** — *all of a sudden* — or **de la nada** — *out of nowhere*. **Para colmo** stacks one more thing on top, like **encima**: **para colmo, llovía**. **Por lo visto** — *apparently* — is what you say when you weren''t there.', 'draft'),
  ('53bd20f9-2fb9-501c-82cb-d4a58c78a952', '1e64d895-153a-5af6-b41e-45c6b9da78d4', 'Nos enteramos, se enteraron', '**Enterarse** for everyone: **nos enteramos tarde** — *we found out late*; **se enteraron todos** — *everybody found out*. The one who tells it best adds **¡ni te cuento!** — *you don''t even want to know*.', 'draft'),
  ('22bb24f8-8694-59d9-9551-1eae8071c382', '685c49ba-32f9-5e23-acab-d8552fdf4a20', 'Me la jugué, la pifié, la rompe', 'More verbs that take a **la** pointing at nothing: **me la juego** — *I''ll go for it*; **la pifié** — *I blew it*; **la rompe** — *she nails it, she kills it*; **se la agarró conmigo** — *he took it out on me*. **Me las tomo** — *I''m out of here*.', 'draft'),
  ('64ddc740-cba3-541e-b01d-38bbf52e9139', '685c49ba-32f9-5e23-acab-d8552fdf4a20', 'Te la bancás, te las arreglás', 'The *la* stays put while the person changes: **me la banco**, **te la bancás**, **nos la bancamos**; **me las arreglo**, **te las arreglás**, **se las arregla**. Two more with the *la* inside: **a las apuradas** — *in a rush* — and **a la larga** — *in the long run*.', 'draft'),
  ('915c227f-3a59-5eb0-8e94-a3be77cd232d', '8fd78797-231c-5920-8d41-337bed37a7a9', 'Te reenvío, para colmo', '**Te reenvío el archivo**, **cualquier duda, avisame**. And the story: **de golpe**, **para colmo**, **por lo visto**.', 'draft'),
  ('83235091-134e-5789-949b-4252689bf7a7', '8fd78797-231c-5920-8d41-337bed37a7a9', 'Me la jugué, la rompe', '**Me la jugué**, **la pifié**, **la rompe**, **te las arreglás** — the *la* again, doing nothing and everything.', 'draft'),
  ('1ff21937-4c97-54d5-9f50-7a6407f83159', 'a3c55aeb-a257-5eb2-ac90-fc258b138c7e', 'Dejé de, volví a', '**Dejar de** + infinitive is *to stop, to quit*: **dejé de fumar**, **¿dejaste de ir al gimnasio?**, **¡dejá de quejarte!** Its opposite is **volver a** — **volvió a fumar** — or **ponerse a**, *to get down to it*: **me puse a estudiar**.', 'draft'),
  ('559eee63-454f-5ebc-885f-9cdf45705eee', 'a3c55aeb-a257-5eb2-ac90-fc258b138c7e', 'Solemos, suelen', 'The other persons of *soler*: **solemos juntarnos los viernes**, **los porteños suelen cenar tarde**. And *acabar de* for everyone: **acabamos de llegar**, **acaban de salir**. How often? **De vez en cuando**, or **casi nunca**.', 'draft'),
  ('6db7132b-f813-53fa-a327-4f6104bca4c9', '6aa47fcd-c4fb-5d93-9c82-3c5580df654a', 'Cambiaste, mejoró, empeoró', 'Change, person by person: **cambiaste un montón**, **cambiaron los precios**, **el barrio mejoró**, **el servicio empeoró**. **Estás cambiado** — *you look different* — agrees like an adjective: *estás cambiada*.', 'draft'),
  ('540d8ca7-657a-5701-bb91-0246d4d77115', '6aa47fcd-c4fb-5d93-9c82-3c5580df654a', 'Cada vez peor, de moda', '**Cada vez peor** and **cada vez mejor** — *worse and worse, better and better*. What''s in is **de moda**; what''s gone **desapareció**: **desaparecieron los almacenes**, and where the old house stood there''s a **torre**. Ya no es **lo mismo**.', 'draft'),
  ('7b596798-1504-5e3c-840b-ce62a7046665', '4f79112a-7e16-5786-a09f-c3f47eec42c1', 'Me pudrí, me harté', 'The moment you snap is in the past: **me harté** — *I got fed up*; porteños say **me pudrí**: **me pudrí y me fui**. Both take **de** + infinitive: **me pudrí de esperar**. Then one word: **¡basta!**', 'draft'),
  ('6f45a3bc-6d31-5a43-8fae-bde8329e1e96', '4f79112a-7e16-5786-a09f-c3f47eec42c1', 'Me quejo, reniego', '**Me quejo** — *I complain*; **reniego** is the Argentine *I struggle with it, I grumble*: **reniego todos los días con el banco**. Someone who''s **agotado** is *wiped out*; the **estrés** is why. And the traffic? **Un caos**.', 'draft'),
  ('68ee52b6-ffc4-510b-819b-25355d531ada', '06acaaed-73cd-553d-a457-b534da4c99d0', 'Dejé de, volví a, solemos', '**Dejé de fumar**, **volvió a correr**, **solemos cenar tarde**, **acabamos de llegar**.', 'draft'),
  ('a08fbeee-bbfa-5c43-b43e-114dd685576d', '06acaaed-73cd-553d-a457-b534da4c99d0', 'Cada vez peor, me pudrí', '**Cambiaste un montón**, **el servicio empeoró**, **cada vez peor** — and then: **me pudrí**, **¡basta!**', 'draft'),
  ('3cb8c2d5-f639-5cac-8a91-fecea363b8c9', '976c0600-48a2-5a5a-9ddb-85af02f42f69', 'Como te decía', 'A porteño story wanders, so it has signposts: **como te decía** — *like I was saying* — brings it back; **el tema es que** — *the thing is* — gets to the point; **a todo esto** — *by the way* — goes off on a side road; **hablando de** jumps to the next story.', 'draft'),
  ('c94d2e69-9d48-539a-a1af-33cdcb771363', '976c0600-48a2-5a5a-9ddb-85af02f42f69', 'Y bueno', '**Y bueno** is the porteño shrug — *oh well, what can you do*: **y bueno, así es**. **Ah, me olvidaba** — *oh, I forgot to say* — adds the best part at the end. A story can be **larga** or **corta**; this one never is.', 'draft')
